  const tikNav = (active: string) => (<nav style={{ display: 'flex', justifyContent: 'space-around', alignItems: 'center', padding: '6px 12px 10px', background: '#000', borderTop: '1px solid #222' }}><button onClick={() => goView('home')} style={{ background: 'none', border: 'none', color: '#fff', textAlign: 'center' }}><div style={{ fontSize: 19 }}>🏠</div><div style={{ fontSize: 9, fontWeight: active === 'home' ? 'bold' : 'normal' }}>Home</div></button><button onClick={() => { stopSound(); setShowTrending(true) }} style={{ background: 'none', border: 'none', color: '#fff', textAlign: 'center' }}><div style={{ fontSize: 19 }}>🔍</div><div style={{ fontSize: 9 }}>Discover</div></button><button onClick={() => { stopSound(); setShowCamera(true) }} style={{ width: 44, height: 30, borderRadius: 10, border: 'none', background: '#fff', color: '#000', fontSize: 19, fontWeight: 'bold', position: 'relative' }}>+<span style={{ position: 'absolute', left: -3, top: 0, bottom: 0, width: 44, height: 30, borderRadius: 10, background: '#25F4EE', zIndex: -1 }} /><span style={{ position: 'absolute', right: -3, top: 0, bottom: 0, width: 44, height: 30, borderRadius: 10, background: '#FE2C55', zIndex: -1 }} /></button><button onClick={() => goView('chat')} style={{ background: 'none', border: 'none', color: '#fff', textAlign: 'center' }}><div style={{ fontSize: 19 }}>💬</div><div style={{ fontSize: 9 }}>Inbox</div></button><button onClick={() => goView('me')} style={{ background: 'none', border: 'none', color: '#fff', textAlign: 'center' }}><div style={{ fontSize: 19 }}>👤</div><div style={{ fontSize: 9, fontWeight: active === 'me' ? 'bold' : 'normal' }}>Me</div></button></nav>)
